const first = $input.first().json;
const rawInput = first['Scam URL'] || first.scamUrl || first.url || '';
let urlStr = String(rawInput).trim();
if (!/^https?:\/\//i.test(urlStr)) { urlStr = 'http://' + urlStr; }
let domain = '';
try {
  domain = new URL(urlStr).hostname.replace(/^www\./, '');
} catch (e) {
  domain = urlStr.replace(/^https?:\/\//i, '').split('/')[0].replace(/^www\./, '');
}
return [{ json: { submittedUrl: urlStr, domain } }];

const item = $input.first().json;
const answers = item.Answer || [];
const aRecord = answers.find(a => a.type === 1);
return [{ json: { ip: aRecord ? aRecord.data : null } }];

const html = ($input.first().json.html) || '';
const gaMatch = html.match(/\b(UA-\d{4,10}-\d{1,4}|G-[A-Z0-9]{6,12})\b/);
const fbPixelMatch = html.match(/fbq\(['"]init['"],\s*['"](\d{10,20})['"]/);
const adsenseMatch = html.match(/\bpub-\d{10,20}\b/);
const faviconMatch = html.match(/<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i);
const btcMatch = html.match(/\b(bc1[a-z0-9]{25,39}|[13][a-km-zA-HJ-NP-Z1-9]{25,34})\b/);
const ethMatch = html.match(/\b0x[a-fA-F0-9]{40}\b/);
const telegramMatch = html.match(/t\.me\/[a-zA-Z0-9_]{5,32}/);
return [{ json: {
  gaOrPixelId: gaMatch ? gaMatch[0] : null,
  fbPixelId: fbPixelMatch ? fbPixelMatch[1] : null,
  adsenseId: adsenseMatch ? adsenseMatch[0] : null,
  faviconUrl: faviconMatch ? faviconMatch[1] : null,
  btcWallet: btcMatch ? btcMatch[0] : null,
  ethWallet: ethMatch ? ethMatch[0] : null,
  telegramContact: telegramMatch ? telegramMatch[0] : null
} }];

const domainInfo = $('Parse Domain from URL').first().json;
const rdap = $('Fetch RDAP Domain Info').first().json || {};
const ipInfoData = $('Fetch IP Hosting Info').first().json || {};
const scanResult = $('Fetch URLScan.io Results').first().json || {};
const fingerprints = $('Parse HTML Fingerprints').first().json || {};
let crtEntries = [];
try {
  const raw = $('Fetch Certificate Transparency Info').first().json.rawCertData || '[]';
  crtEntries = JSON.parse(raw);
} catch (e) { crtEntries = []; }
const relatedDomainsFromCert = [...new Set(crtEntries.flatMap(c => (c.name_value || '').split('\n')))].filter(d => d && d !== domainInfo.domain);
const regEvent = (rdap.events || []).find(e => e.eventAction === 'registration');
return [{ json: {
  domain: domainInfo.domain,
  submittedUrl: domainInfo.submittedUrl,
  registrar: rdap.handle || (rdap.port43 || 'unknown'),
  domainCreated: regEvent ? regEvent.eventDate : null,
  relatedDomainsFromCert,
  ip: ipInfoData.ip || null,
  hostingOrg: ipInfoData.org || null,
  hostingCity: ipInfoData.city || null,
  hostingCountry: ipInfoData.country || null,
  abuseContact: (ipInfoData.abuse && ipInfoData.abuse.address) || null,
  gaOrPixelId: fingerprints.gaOrPixelId || null,
  fbPixelId: fingerprints.fbPixelId || null,
  adsenseId: fingerprints.adsenseId || null,
  faviconUrl: fingerprints.faviconUrl || null,
  btcWallet: fingerprints.btcWallet || null,
  ethWallet: fingerprints.ethWallet || null,
  telegramContact: fingerprints.telegramContact || null,
  urlscanReportUrl: (scanResult.task && scanResult.task.uuid) ? ('https://urlscan.io/result/' + scanResult.task.uuid + '/') : null,
  investigatedAt: new Date().toISOString()
} }];

const current = $('Combine All Findings').first().json;
const priorRows = $input.all().map(i => i.json);
const fingerprintFields = ['gaOrPixelId', 'fbPixelId', 'adsenseId', 'faviconUrl', 'btcWallet', 'ethWallet', 'telegramContact'];
const relatedCases = [];
for (const row of priorRows) {
  if (!row || row.domain === current.domain) continue;
  const matches = fingerprintFields.filter(f => current[f] && row[f] && current[f] === row[f]);
  if (matches.length > 0) { relatedCases.push({ domain: row.domain, matchedOn: matches, investigatedAt: row.investigatedAt }); }
}
return [{ json: Object.assign({}, current, { relatedCases }) }];

